            ];

            // Calculate position for floating icon wrapper
            function moveFloatingIcon(index) {
                const tab = tabs[index];
                const tabRect = tab.getBoundingClientRect();
                const containerRect = menuContainer.getBoundingClientRect();

                // Calculate center position of the clicked tab relative to the container
                const tabCenter = tabRect.left + (tabRect.width / 2) - containerRect.left;
                const iconOffset = 40; // Half of floating icon width (80px / 2)

                floatingIconWrapper.style.left = `${tabCenter - iconOffset}px`;
                floatingIcon.innerHTML = tabIcons[index];
            }

            tabs.forEach((tab, index) => {
                tab.addEventListener('click', function () {
                    const targetTab = this.getAttribute('data-tab');

                    // Remove active class from all tabs
                    tabs.forEach(t => t.classList.remove('active'));

                    // Add active class to clicked tab
                    this.classList.add('active');

                    // Move and update floating icon
                    moveFloatingIcon(index);
                    floatingIcon.classList.add('active');

                    // Hide all cards with fade out
                    cards.forEach(card => {
                        card.classList.remove('show');
                        setTimeout(() => {
                            card.style.display = 'none';
                        }, 300);
                    });

                    // Show relevant cards with staggered animation
                    setTimeout(() => {
                        const targetCards = document.querySelectorAll(
                            `[data-content="${targetTab}"]`);
                        targetCards.forEach((card, cardIndex) => {
                            card.style.display = 'block';
                            setTimeout(() => {
                                card.classList.add('show');
                            }, cardIndex * 150);
                        });
                    }, 350);
                });
            });

            // Initialize position on load
            moveFloatingIcon(0);
        });
    </script>
    <!-- Tab pane for faq -->
    <script>
        const oneTimeTab = document.getElementById('oneTimeTab');
        const emiTab = document.getElementById('emiTab');
        const priceText = document.getElementById('priceText');
        const emiText = document.getElementById('emiText');

        // initial state: One Time active, show price, hide EMI
        oneTimeTab.classList.add('active-tab');
        emiTab.classList.remove('active-tab');
        priceText.style.display = 'block';
        emiText.style.display = 'none';

        function showOneTime() {
            oneTimeTab.classList.add('active-tab');
            emiTab.classList.remove('active-tab');

            priceText.style.display = 'block';
            emiText.style.display = 'none';
        }

        function showEmi() {
            emiTab.classList.add('active-tab');
            oneTimeTab.classList.remove('active-tab');

            priceText.style.display = 'none';
            emiText.style.display = 'block';
        }

        oneTimeTab.addEventListener('click', showOneTime);
        emiTab.addEventListener('click', showEmi);
    </script>
    <!-- custom Animation js will be here -->
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const cards = document.querySelectorAll('.projects-card .cardd');
            cards.forEach(card => {
                const learnMore = card.querySelector('.learn-more');
                if (!learnMore) return;

                learnMore.addEventListener('click', (e) => {
                    e.stopPropagation();
                    card.classList.add('is-open');
                })

                card.addEventListener('mouseleave', (e) => {
                    e.stopPropagation();
                    card.classList.remove('is-open');
                })



            });
        })
    </script>


